using ClosedXML.Excel;
using Microsoft.EntityFrameworkCore;
using QL_KhachSan.DangNhap;
using QL_KhachSan.Models;

namespace QL_KhachSan.TaiKhoan;

internal abstract class AccountEditorForm : Form
{
    private sealed record Employee(string MaNV,string TenNV){public override string ToString()=>$"{MaNV} - {TenNV}";}
    private readonly string? _original;private readonly TextBox _username=HotelUi.TextBox();private readonly TextBox _password=HotelUi.TextBox();private readonly ComboBox _employee=new(){DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};private readonly ComboBox _level=new(){DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};
    protected AccountEditorForm(string? username){_original=username;var editing=username is not null;Text=editing?"Cập nhật tài khoản":"Thêm tài khoản";StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=MinimizeBox=false;ClientSize=new Size(630,380);_username.MaxLength=50;_password.MaxLength=100;_password.UseSystemPasswordChar=true;_level.Items.AddRange(["3","2","1","0"]);var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(20),ColumnCount=2,RowCount=5};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,180));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.Controls.Add(HotelUi.Heading(editing?"Cập nhật thông tin tài khoản":"Thêm thông tin tài khoản"),0,0);root.SetColumnSpan(root.Controls[0],2);Add(root,1,"Tên tài khoản",_username);Add(root,2,"Mật khẩu",_password);Add(root,3,"Nhân viên",_employee);Add(root,4,"Cấp độ quyền",_level);var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=54,FlowDirection=FlowDirection.RightToLeft};var save=HotelUi.Button(editing?"Cập nhật":"Thêm mới",true);var cancel=HotelUi.Button("Thoát");save.Click+=(_,_)=>Save();cancel.Click+=(_,_)=>{DialogResult=DialogResult.Cancel;Close();};Controls.Add(root);Controls.Add(buttons);buttons.Controls.AddRange([cancel,save]);Load+=(_,_)=>LoadData();}
    private static void Add(TableLayoutPanel p,int r,string caption,Control c){p.RowStyles.Add(new RowStyle(SizeType.Absolute,50));p.Controls.Add(HotelUi.FieldLabel(caption),0,r);c.Margin=new Padding(5);p.Controls.Add(c,1,r);}
    private void LoadData(){try{using var db=new HotelManagementContext();var employees=db.NhanViens.AsNoTracking().Where(e=>e.DaXoa!=true).OrderBy(e=>e.MaNv).Select(e=>new Employee(e.MaNv,e.TenNv)).ToList();_employee.DataSource=employees;if(_original is null){_level.SelectedIndex=2;if(employees.Count==0){MessageBox.Show("Chưa có nhân viên để tạo tài khoản.");Close();}}else{_employee.Enabled=false;var account=db.TaiKhoans.AsNoTracking().FirstOrDefault(t=>t.TenTk==_original&&t.DaXoa!=true);if(account is null){MessageBox.Show("Không tìm thấy tài khoản.");Close();return;}_username.Text=account.TenTk;_password.Text=account.Password;_employee.SelectedItem=employees.FirstOrDefault(e=>e.MaNV==account.MaNv);var pos=_level.Items.Cast<string>().ToList().FindIndex(x=>string.Equals(x,account.CapDoQuyen.ToString(),StringComparison.Ordinal));_level.SelectedIndex=pos;}}catch(Exception ex){MessageBox.Show("Lỗi tải thông tin tài khoản: "+ex.GetBaseException().Message);Close();}}
    private void Save(){var name=_username.Text.Trim();var password=_password.Text;var employee=_employee.SelectedItem as Employee;if(name.Length==0||password.Length==0||employee is null||_level.SelectedIndex<0){MessageBox.Show("Vui lòng nhập đầy đủ thông tin.");return;}var level=int.Parse(_level.SelectedItem!.ToString()!.Split('-')[0].Trim());try{using var db=new HotelManagementContext();if(_original is null){var previous=db.TaiKhoans.FirstOrDefault(x=>x.TenTk==name);if(previous is {DaXoa:not true}){MessageBox.Show("Tên tài khoản đã tồn tại.");_username.Focus();return;}if(db.TaiKhoans.Any(x=>x.MaNv==employee.MaNV&&x.DaXoa!=true)){MessageBox.Show("Nhân viên này đã có tài khoản.");return;}if(previous is null)db.TaiKhoans.Add(new QL_KhachSan.Models.TaiKhoan{TenTk=name,Password=password,MaNv=employee.MaNV,CapDoQuyen=level,DaXoa=false});else{previous.Password=password;previous.MaNv=employee.MaNV;previous.CapDoQuyen=level;previous.DaXoa=false;}}else{if(name!=_original&&db.TaiKhoans.Any(x=>x.TenTk==name)){MessageBox.Show("Tên tài khoản đã tồn tại.");return;}var old=db.TaiKhoans.FirstOrDefault(x=>x.TenTk==_original&&x.DaXoa!=true);if(old is null)throw new InvalidOperationException("Không tìm thấy tài khoản.");if(name==_original){old.Password=password;old.CapDoQuyen=level;}else{var changed=db.TaiKhoans.Where(x=>x.TenTk==_original&&x.DaXoa!=true).ExecuteUpdate(s=>s.SetProperty(x=>x.TenTk,name).SetProperty(x=>x.Password,password).SetProperty(x=>x.CapDoQuyen,level));if(changed==0)throw new InvalidOperationException("Không cập nhật được tài khoản.");}}db.SaveChanges();MessageBox.Show(_original is null?"Thêm tài khoản thành công.":"Cập nhật tài khoản thành công.","Thành công",MessageBoxButtons.OK,MessageBoxIcon.Information);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show("Lỗi lưu tài khoản: "+ex.GetBaseException().Message,"Lỗi",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}
